package main

import (
	"context"
	"errors"
	"fmt"
	"io/fs"
	"log"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	s "github.com/ShearlingEnMouton/homeproject/homeprojectserver"
	"github.com/ShearlingEnMouton/homeproject/web"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/joho/godotenv"
)

func main() {
	if err := godotenv.Load(); err != nil && !errors.Is(err, fs.ErrNotExist) {
		log.Fatalf("load .env: %v", err)
	}

	var ok bool
	s.DBHostname, ok = os.LookupEnv("DB_HOST")
	if !ok {
		log.Fatalf("missing env DB_HOST")
	}
	s.DBPort, ok = os.LookupEnv("DB_PORT")
	if !ok {
		log.Fatalf("missing env DB_PORT")
	}
	s.DBUser, ok = os.LookupEnv("DB_USER")
	if !ok {
		log.Fatalf("missing env DB_USER")
	}
	s.DBPassword, ok = os.LookupEnv("DB_PASSWORD")
	if !ok {
		log.Fatalf("missing env DB_PASSWORD")
	}
	s.DBName, ok = os.LookupEnv("DB_NAME")
	if !ok {
		log.Fatalf("missing env DB_NAME")
	}

	var err error
	s.DBConn, err = pgxpool.New(context.Background(), s.DBUrl())
	if err != nil {
		log.Fatalf("Failed to connect to the DB: %s", err)
	}
	defer s.DBConn.Close()

	s.MQTTBroker, ok = os.LookupEnv("MQTT_BROKER")
	if !ok {
		log.Fatalf("missing env MQTT_BROKER")
	}
	s.MQTTUser, ok = os.LookupEnv("MQTT_USER")
	if !ok {
		log.Fatalf("missing env MQTT_USER")
	}
	s.MQTTPassword, ok = os.LookupEnv("MQTT_PASSWORD")
	if !ok {
		log.Fatalf("missing env MQTT_PASSWORD")
	}
	s.MQTTClientID, ok = os.LookupEnv("MQTT_CLIENT_ID")
	if !ok {
		log.Fatalf("missing env MQTT_CLIENT_ID")
	}

	if err := s.ConnectMQTT(); err != nil {
		log.Fatalf("Failed to connect to MQTT: %s", err)
	}
	defer s.MQTTClient.Disconnect(250)

	s.ApplicationId, ok = os.LookupEnv("APPLICATION_ID")
	if !ok {
		log.Fatalf("missing env APPLICATION_ID")
	}

	// Meteo-France integration is optional: it only turns on once a station ID
	// and home coordinates are configured, so the app keeps running fine without it.
	s.MeteoFranceStationID = os.Getenv("METEOFRANCE_STATION_ID")
	latStr, hasLat := os.LookupEnv("METEOFRANCE_LAT")
	lonStr, hasLon := os.LookupEnv("METEOFRANCE_LON")
	s.MeteoFranceEnabled = s.MeteoFranceStationID != "" && hasLat && hasLon
	if s.MeteoFranceEnabled {
		s.MeteoFranceLat, err = strconv.ParseFloat(latStr, 64)
		if err != nil {
			log.Fatalf("invalid env METEOFRANCE_LAT: %s", err)
		}
		s.MeteoFranceLon, err = strconv.ParseFloat(lonStr, 64)
		if err != nil {
			log.Fatalf("invalid env METEOFRANCE_LON: %s", err)
		}
		s.StartMeteoFranceScheduler(context.Background())
		log.Printf("Meteo-France integration enabled for station %s", s.MeteoFranceStationID)
	} else {
		log.Printf("Meteo-France integration disabled (set METEOFRANCE_STATION_ID, METEOFRANCE_LAT, METEOFRANCE_LON to enable)")
	}

	termChan := make(chan os.Signal, 1)
	signal.Notify(termChan, syscall.SIGTERM, os.Interrupt) // Received after the preStop hook

	router := s.NewRouter("")
	router.PathPrefix("/").Handler(web.Handler())

	server := http.Server{
		Addr:    fmt.Sprintf(":%v", 8080),
		Handler: router,
	}

	errChan := make(chan error, 1)
	go func() {
		log.Printf("Server started hosting 'Homeproject API' on %s", server.Addr)
		if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			errChan <- err
		}
	}()

	select {
	case err := <-errChan:
		log.Fatalf("server error: %v", err)
	case c := <-termChan:
		log.Printf("Received signal %v, stopping gracefully", c)
		ctx, cancel := context.WithTimeout(context.Background(), time.Second*10)
		defer cancel()
		server.Shutdown(ctx)
		log.Printf("Server stopped, exiting. ")
	}
}
